-- M5 precedent bank (#901, ADR 0046): precedent_passage is a tenant table under FORCE RLS (ws_isolation). On top of that:
--   * precedent_passage_item_scope (RESTRICTIVE): a passage is visible only when its memory_item is visible, which applies memory_item_owner_scope (owner only, unless the owner shared the item with the chamber).
--   * the clerk role has no privilege on the table; M5 is never in memory_clerk_readable, so clerks do not see M5 items through memory_item_clerk_v either.
--   * memory_item and memory_proposal accept layer M5, and memory_item_shared_chk lets M4 and M5 items be shared with the chamber.
-- The layer and shared CHECKs are widened (dropped and re-added, no row can violate the wider rule). app_memory_purge_targets() already covers M5: it selects any deleted item that still has an embedding.
CREATE TABLE "precedent_passage" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"memory_item_id" uuid NOT NULL,
	"court_id" uuid,
	"kind" text NOT NULL,
	"language" text DEFAULT 'en' NOT NULL,
	"body_ciphertext" text,
	"source_draft_version_id" uuid NOT NULL,
	"anchor_id" text NOT NULL,
	"status" text DEFAULT 'active' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "precedent_passage_item_uq" UNIQUE("workspace_id","memory_item_id"),
	CONSTRAINT "precedent_passage_kind_chk" CHECK (kind in ('prayer', 'ground', 'facts', 'averment', 'argument', 'annexure_list', 'other')),
	CONSTRAINT "precedent_passage_status_chk" CHECK (status in ('active', 'retired', 'deleted')),
	CONSTRAINT "precedent_passage_body_chk" CHECK ((status = 'deleted') = (body_ciphertext is null))
);
